robot-arm.project.vaproject:
{
  "schemaVersion": 1,
  "name": "Pick-and-place arm",
  "description": "A sample of the Physical AI and robotics package: a six-axis arm drawn as a solid you can turn, its links and joints anchored to its parts, the motors and encoders at its joints, the learned policy and the controller that move it, and the software they run in; and its workcell, with a table and two bins, where physical space shows each where it is.",
  "packages": [
    "physical-ai",
    "robot-arm"
  ]
}

robot-arm.scenarios/pick-a-part.vascenario:
{
  "id": "pick-a-part",
  "name": "Pick a part",
  "description": "The arm picks a part from its tray: the camera sees it, the policy picks joint targets, the controller and the motors move the arm to it, the encoders read each joint back, and the gripper closes on it.",
  "view": "control-loop",
  "steps": [
    {
      "id": "see",
      "description": "The wrist camera sees the part on its tray, 30 times a second.",
      "relations": [
        "camera-sees-workpiece"
      ],
      "dataOut": {
        "frames": 30
      }
    },
    {
      "id": "decide",
      "description": "From the camera’s images, the policy picks the next joint targets, 10 times a second.",
      "relations": [
        "policy-commands-controller"
      ],
      "dataOut": {
        "joint1": 35,
        "joint2": 42,
        "joint3": 32
      }
    },
    {
      "id": "reach",
      "description": "The joint controller turns each joint’s error into a torque for its motor, 1,000 times a second.",
      "relations": [
        "controller-commands-motor-1",
        "controller-commands-motor-2",
        "controller-commands-motor-3"
      ],
      "dataIn": {
        "error": 35
      },
      "dataOut": {
        "torque": 42.5
      }
    },
    {
      "id": "move",
      "description": "Motors 1 to 3 turn the arm toward the part and lower it over the tray.",
      "relations": [
        "motor-1-drives-joint-1",
        "motor-2-drives-joint-2",
        "motor-3-drives-joint-3"
      ]
    },
    {
      "id": "read-back",
      "description": "The encoders read the joints’ new angles back to the controller, closing the loop.",
      "relations": [
        "encoder-1-senses-joint-1",
        "encoder-2-senses-joint-2",
        "encoder-3-senses-joint-3"
      ],
      "dataOut": {
        "angle": 34.8
      }
    },
    {
      "id": "orient",
      "description": "Motors 4 to 6 roll the forearm, bend the wrist and turn the gripper to face the part.",
      "relations": [
        "controller-commands-motor-4",
        "controller-commands-motor-5",
        "controller-commands-motor-6",
        "motor-4-drives-joint-4",
        "motor-5-drives-joint-5",
        "motor-6-drives-joint-6"
      ]
    },
    {
      "id": "grasp",
      "description": "Over the part, the policy closes the gripper on it.",
      "relations": [
        "policy-commands-gripper"
      ]
    }
  ]
}

robot-arm.tours/pick-a-part.vatour:
{
  "id": "pick-a-part",
  "name": "Pick a part",
  "description": "The arm in its workcell, and one pick from bin A, followed on the control loop and in physical space side by side.",
  "steps": [
    {
      "id": "the-workcell",
      "viewState": {
        "view": "workcell",
        "space": {
          "camera": {
            "target": {
              "x": 0,
              "y": 1,
              "z": 0
            },
            "azimuth": 35,
            "elevation": 25,
            "distance": 3.6
          },
          "names": true
        }
      },
      "caption": {
        "title": "The workcell",
        "text": "The arm is bolted to the back of its table, a bin in front of it on either side: it picks each part from bin A and places it in bin B. A camera hangs above the bins.\n\nBeside the canvas, physical space shows each of them where it is, in meters."
      },
      "marks": [
        "arm",
        "bin-a",
        "bin-b",
        "workcell-camera"
      ]
    },
    {
      "id": "the-wrist-camera",
      "viewState": {
        "view": "kinematic-chain",
        "select": [
          "wrist-camera"
        ],
        "space": {
          "root": "arm",
          "camera": {
            "target": {
              "x": 0,
              "y": 0.72,
              "z": 0.5
            },
            "azimuth": 60,
            "elevation": 20,
            "distance": 0.9
          }
        }
      },
      "caption": {
        "title": "The wrist camera",
        "text": "The wrist camera is mounted on link 6, the tool flange, just above the gripper. It is posed in link 6, so it goes wherever the arm takes the flange, and looks past the gripper at the part it is about to pick.",
        "pointTo": "wrist-camera"
      },
      "marks": [
        "wrist-camera",
        "camera-on-link-6",
        "link-6"
      ]
    },
    {
